  )
}) }}

parameters.jsCode:
const input = $("Normalize Telegram Input").item.json;

let classifierResult = '';

try {
  const classifierData =
    $("Classify Off-Script Message").item.json;

  classifierResult = String(
    classifierData.text ||
    classifierData.output ||
    classifierData.response ||
    classifierData.content ||
    ''
  )
    .trim()
    .toUpperCase();
} catch (error) {
  classifierResult = '';
}

const store = $getWorkflowStaticData('global');

if (!store.slotwiseSessions) {
  store.slotwiseSessions = {};
}

const chatKey = String(input.chat_id);
const originalText = String(input.message_text || '').trim();
const text = originalText.toLowerCase();

let session = store.slotwiseSessions[chatKey] || {
  stage: 'awaiting_booking_type',
  booking_type: '',
  service: '',
  preferred_time: '',
  selected_slot: '',
};

const mainMenu =
  `Welcome to SlotWise, ${input.first_name || 'Guest'}!\n\n` +
  `What would you like to book?\n\n` +
  `1. Restaurant Table\n` +
  `2. Parlour Appointment\n\n` +
  `Reply with 1 or 2.`;

let replyText = '';

let shouldLogBooking = false;
let bookingId = '';

let shouldLogHandoff = false;
let handoffId = '';
let handoffReason = '';

const resetCommands = [
  '/start',
  'start',
  '/reset',
  'reset',
  '/restart',
  'restart',
  '/menu',
  'menu',
];

const explicitHandoffPattern =
  /\b(price|prices|pricing|expensive|discount|negotiate|negotiation|complaint|complain|refund|angry|manager|human|staff|team|representative|customer support|speak to someone|talk to someone)\b/i;

const explicitHandoff =
  explicitHandoffPattern.test(originalText);

const llmHandoff =
  classifierResult.includes('HANDOFF');

const timePattern =
  /\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|morning|afternoon|evening|night|\d{1,2}(:\d{2})?\s*(am|pm))\b/i;

const looksLikeTiming =
  timePattern.test(originalText);

function createHandoffReply(reason) {
  shouldLogHandoff = true;
  handoffId = `HF-${Date.now()}-${input.chat_id}`;
  handoffReason = reason;

  return (
    `I could not handle this request automatically.\n\n` +
    `Let me connect you with our team. Someone will assist you soon.`
  );
}

/*
|--------------------------------------------------------------------------
| Start or reset
|--------------------------------------------------------------------------
*/

if (resetCommands.includes(text)) {
  session = {
    stage: 'awaiting_booking_type',
    booking_type: '',
    service: '',
    preferred_time: '',
    selected_slot: '',
  };

  replyText = mainMenu;
}

/*
|--------------------------------------------------------------------------
| Booking type
|--------------------------------------------------------------------------
*/

else if (session.stage === 'awaiting_booking_type') {
  const restaurantInputs = [
    '1',
    'restaurant',
    'table',
    'restaurant table',
    'book table',
  ];

  const parlourInputs = [
    '2',
    'parlour',
    'salon',
    'appointment',
    'parlour appointment',
  ];

  if (restaurantInputs.includes(text)) {
    session.booking_type = 'Restaurant Table';
    session.stage = 'awaiting_service';

    replyText =
      `Restaurant booking selected.\n\n` +
      `Please choose the table type:\n\n` +
      `1. Table for 2\n` +
      `2. Table for 4\n` +
      `3. Birthday / Special Occasion\n\n` +
      `Reply with 1, 2, or 3.`;
  }

  else if (parlourInputs.includes(text)) {
    session.booking_type = 'Parlour Appointment';
    session.stage = 'awaiting_service';

    replyText =
      `Parlour appointment selected.\n\n` +
      `Please choose a service:\n\n` +
      `1. Haircut\n` +
      `2. Facial\n` +
      `3. Manicure\n\n` +
      `Reply with 1, 2, or 3.`;
  }

  else if (explicitHandoff || llmHandoff) {
    replyText = createHandoffReply(
      explicitHandoff
        ? 'Complaint, pricing, or human-support request'
        : 'Off-script message detected by Groq'
    );
  }

  else {
    replyText =
      `I could not understand your selection.\n\n` +
      `Please reply with:\n` +
      `1 for Restaurant Table\n` +
      `2 for Parlour Appointment`;
  }
}

/*
|--------------------------------------------------------------------------
| Service or table type
|--------------------------------------------------------------------------
*/

else if (session.stage === 'awaiting_service') {
  let selectedService = '';

  if (session.booking_type === 'Restaurant Table') {
    const restaurantServices = {
      '1': 'Table for 2',
      '2': 'Table for 4',
      '3': 'Birthday / Special Occasion',
      'table for 2': 'Table for 2',
      'table for 4': 'Table for 4',
      'birthday': 'Birthday / Special Occasion',
      'special occasion': 'Birthday / Special Occasion',
    };

    selectedService = restaurantServices[text] || '';
  }

  else if (session.booking_type === 'Parlour Appointment') {
    const parlourServices = {
      '1': 'Haircut',
      '2': 'Facial',
      '3': 'Manicure',
      'haircut': 'Haircut',
      'facial': 'Facial',
      'manicure': 'Manicure',
    };

    selectedService = parlourServices[text] || '';
  }

  if (selectedService) {
    session.service = selectedService;
    session.stage = 'awaiting_timing';

    replyText =
      `You selected: ${selectedService}\n\n` +
      `What day and approximate time would you prefer?\n\n` +
      `Example: Friday at 7 PM`;
  }

  else if (explicitHandoff || llmHandoff) {
    replyText = createHandoffReply(
      explicitHandoff
        ? 'Complaint, pricing, or human-support request'
        : 'Off-script message detected by Groq'
    );
  }

  else if (session.booking_type === 'Restaurant Table') {
    replyText =
      `Please choose a valid table type:\n\n` +
      `1. Table for 2\n` +
      `2. Table for 4\n` +
      `3. Birthday / Special Occasion`;
  }

  else {
    replyText =
      `Please choose a valid service:\n\n` +
      `1. Haircut\n` +
      `2. Facial\n` +
      `3. Manicure`;
  }
}

/*
|--------------------------------------------------------------------------
| Preferred timing
|--------------------------------------------------------------------------
*/

else if (session.stage === 'awaiting_timing') {
  if (!originalText) {
    replyText =
      `Please send your preferred day and time.\n\n` +
      `Example: Friday at 7 PM`;
  }

  else if (
    explicitHandoff ||
    (llmHandoff && !looksLikeTiming)
  ) {
    replyText = createHandoffReply(
      explicitHandoff
        ? 'Complaint, pricing, or human-support request'
        : 'Off-script message detected by Groq'
    );
  }

  else {
    session.preferred_time = originalText;
    session.stage = 'awaiting_slot';

    replyText =
      `Based on "${originalText}", these slots are available:\n\n` +
      `1. 6:00 PM\n` +
      `2. 7:00 PM\n` +
      `3. 8:00 PM\n\n` +
      `Reply with 1, 2, or 3.`;
  }
}

/*
|--------------------------------------------------------------------------
| Slot selection
|--------------------------------------------------------------------------
*/

else if (session.stage === 'awaiting_slot') {
  const slots = {
    '1': '6:00 PM',
    '2': '7:00 PM',
    '3': '8:00 PM',
    '6:00 pm': '6:00 PM',
    '6 pm': '6:00 PM',
    '7:00 pm': '7:00 PM',
    '7 pm': '7:00 PM',
    '8:00 pm': '8:00 PM',
    '8 pm': '8:00 PM',
  };

  const selectedSlot = slots[text] || '';

  if (selectedSlot) {
    session.selected_slot = selectedSlot;
    session.stage = 'awaiting_confirmation';

    replyText =
      `Please confirm your booking:\n\n` +
      `Booking: ${session.booking_type}\n` +
      `Service: ${session.service}\n` +
      `Preferred timing: ${session.preferred_time}\n` +
      `Selected slot: ${session.selected_slot}\n\n` +
      `Reply YES to confirm or NO to cancel.`;
  }

  else if (explicitHandoff || llmHandoff) {
    replyText = createHandoffReply(
      explicitHandoff
        ? 'Complaint, pricing, or human-support request'
        : 'Off-script message detected by Groq'
    );
  }

  else {
    replyText =
      `Please choose one available slot:\n\n` +
      `1. 6:00 PM\n` +
      `2. 7:00 PM\n` +
      `3. 8:00 PM`;
  }
}

/*
|--------------------------------------------------------------------------
| Confirmation
|--------------------------------------------------------------------------
*/

else if (session.stage === 'awaiting_confirmation') {
  if (['yes', 'y', 'confirm'].includes(text)) {
    shouldLogBooking = true;
    bookingId = `BK-${Date.now()}-${input.chat_id}`;
    session.stage = 'confirmed';

    replyText =
      `Your booking has been confirmed.\n\n` +
      `Booking: ${session.booking_type}\n` +
      `Service: ${session.service}\n` +
      `Preferred timing: ${session.preferred_time}\n` +
      `Selected slot: ${session.selected_slot}\n\n` +
      `Thank you for using SlotWise.`;
  }

  else if (['no', 'n', 'cancel'].includes(text)) {
    session = {
      stage: 'awaiting_booking_type',
      booking_type: '',
      service: '',
      preferred_time: '',
      selected_slot: '',
    };

    replyText =
      `Your booking has been cancelled.\n\n` +
      `Send /start to make another booking.`;
  }

  else if (explicitHandoff || llmHandoff) {
    replyText = createHandoffReply(
      explicitHandoff
        ? 'Complaint, pricing, or human-support request'
        : 'Off-script message detected by Groq'
    );
  }

  else {
    replyText =
      `Please reply YES to confirm or NO to cancel.`;
  }
}

/*
|--------------------------------------------------------------------------
| Already confirmed
|--------------------------------------------------------------------------
*/

else if (session.stage === 'confirmed') {
  if (explicitHandoff || llmHandoff) {
    replyText = createHandoffReply(
      explicitHandoff
        ? 'Complaint, pricing, or human-support request'
        : 'Off-script message detected by Groq'
    );
  }

  else {
    replyText =
      `Your booking is already confirmed.\n\n` +
      `Send /start to make another booking.`;
  }
}

/*
|--------------------------------------------------------------------------
| Unknown state
|--------------------------------------------------------------------------
*/

else {
  session = {
    stage: 'awaiting_booking_type',
    booking_type: '',
    service: '',
    preferred_time: '',
    selected_slot: '',
  };

  replyText = mainMenu;
}

store.slotwiseSessions[chatKey] = session;

return [
  {
    json: {
      ...input,

      classifier_result: classifierResult,

      stage: session.stage,
      booking_type: session.booking_type,
      service: session.service,
      preferred_time: session.preferred_time,
      selected_slot: session.selected_slot,

      reply_text: replyText,

      is_confirmed: session.stage === 'confirmed',

      should_log_booking: shouldLogBooking,
      booking_id: bookingId,

      should_log_handoff: shouldLogHandoff,
      handoff_id: handoffId,
      handoff_reason: handoffReason,
    },
  },
];
